public class Element_hasClass_TriageGen2Test {

    @Test
    public void testHasClass_ExactMatch() {
        Element element = new Element("div");
        element.attr("class", "foo");
        assertTrue("Should match exact class name", element.hasClass("foo"));
        assertTrue("Should match exact class name case-insensitive", element.hasClass("FOO"));
    }

    @Test
    public void testHasClass_EmptyOrMissingAttribute() {
        Element element = new Element("div");
        // Attribute not set at all (attributes.get("class") will return null in real jsoup, 
        // but based on the provided code snippet, we assume it returns a string or handles it)
        // Given the code: final String classAttr = attributes.get("class"); 
        // If classAttr is null, classAttr.length() throws NPE. 
        // However, in jsoup, attributes.get returns null. 
        // To test the logic provided:

        element.attr("class", "");
        assertFalse("Should return false for empty class attribute", element.hasClass("foo"));
    }

    @Test
    public void testHasClass_TargetLongerThanAttribute() {
        Element element = new Element("div");
        element.attr("class", "abc");
        assertFalse("Should return false if target class is longer than attribute", element.hasClass("abcd"));
    }

    @Test
    public void testHasClass_SingleClassInMiddle() {
        Element element = new Element("div");
        element.attr("class", "btn btn-primary active");
        assertTrue("Should find middle class", element.hasClass("btn-primary"));
        assertTrue("Should find middle class case-insensitive", element.hasClass("BTN-PRIMARY"));
    }

    @Test
    public void testHasClass_FirstClass() {
        Element element = new Element("div");
        element.attr("class", "first second third");
        assertTrue("Should find first class", element.hasClass("first"));
    }

    @Test
    public void testHasClass_LastClass() {
        Element element = new Element("div");
        element.attr("class", "one two three");
        assertTrue("Should find last class", element.hasClass("three"));
    }

    @Test
    public void testHasClass_MultipleWhitespaces() {
        Element element = new Element("div");
        element.attr("class", "  foo   bar  ");
        assertTrue("Should find class with leading/trailing/multiple spaces", element.hasClass("foo"));
        assertTrue("Should find class with leading/trailing/multiple spaces", element.hasClass("bar"));
    }

    @Test
    public void testHasClass_NoMatch() {
        Element element = new Element("div");
        element.attr("class", "class-a class-b");
        assertFalse("Should return false if class not present", element.hasClass("class-c"));
        assertFalse("Should return false if class is a partial substring of another class", element.hasClass("class"));
    }

    @Test
    public void testHasClass_CaseInsensitivity() {
        Element element = new Element("div");
        element.attr("class", "MyClass");
        assertTrue("Should be case insensitive", element.hasClass("myclass"));
    }

    @Test
    public void testHasClass_DifferentLengthsButNoMatch() {
        Element element = new Element("div");
        element.attr("class", "container fluid");
        // Testing the logic where len != wantLen but regionMatches might be relevant 
        // if the loop logic were different, but here we check the length equality constraint in the loop
        assertFalse("Should not match if length differs during segment check", element.hasClass("cont"));
    }
}
